"""Abstract interface for memory systems."""

import hashlib
import json
import re
import threading
from abc import ABC, abstractmethod
from typing import Any

from .llm import LLMCallable


def extract_json_field(text: str, field: str, default: str = "") -> str:
    """Helper function to extract a field from JSON in LLM response."""
    # Try direct parse
    try:
        data = json.loads(text)
        if isinstance(data, dict):
            return str(data.get(field, default))
    except json.JSONDecodeError:
        pass

    # Try code blocks: ```json ... ``` or ``` ... ```
    for match in re.finditer(r"```(?:json)?\s*([\s\S]*?)\s*```", text):
        try:
            data = json.loads(match.group(1))
            if isinstance(data, dict):
                return str(data.get(field, default))
        except json.JSONDecodeError:
            pass

    # Find balanced braces and try parsing
    for start in range(len(text)):
        if text[start] != "{":
            continue
        depth, pos, in_str = 1, start + 1, False
        while pos < len(text) and depth > 0:
            c = text[pos]
            if c == '"' and (pos == 0 or text[pos - 1] != "\\"):
                in_str = not in_str
            elif not in_str:
                depth += 1 if c == "{" else (-1 if c == "}" else 0)
            pos += 1
        if depth == 0:
            candidate = text[start:pos]
            candidate = re.sub(
                r",\s*([\]}])", r"\1", candidate
            )  # Remove trailing commas
            try:
                data = json.loads(candidate)
                if isinstance(data, dict):
                    return str(data.get(field, default))
            except json.JSONDecodeError:
                pass

    # Regex fallback
    match = re.findall(rf'"{field}"\s*:\s*"([^"]*)"', text)
    return match[-1] if match else default


class MemorySystem(ABC):
    """Memory system interface for online and offline learning.

    Args:
        llm: Callable that takes a prompt string and returns a response string.
    """

    def __init__(self, llm: LLMCallable):
        self._llm = llm
        self._prompt_local = threading.local()

    def call_llm(self, prompt: str) -> str:
        """Call the LLM with a prompt. Tracks last prompt length/hash per thread."""
        self._prompt_local.last_prompt_len = len(prompt)
        self._prompt_local.last_prompt_hash = hashlib.md5(prompt.encode()).hexdigest()[
            :8
        ]
        self._prompt_local.last_prompt_text = prompt
        return self._llm(prompt)

    def get_last_prompt_info(self) -> dict[str, Any]:
        """Return length, hash, and full text of the last prompt sent via call_llm (thread-local)."""
        return {
            "prompt_len": getattr(self._prompt_local, "last_prompt_len", None),
            "prompt_hash": getattr(self._prompt_local, "last_prompt_hash", None),
            "prompt_text": getattr(self._prompt_local, "last_prompt_text", None),
        }

    @abstractmethod
    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction BEFORE seeing ground truth. Returns (answer, metadata)."""
        pass

    @abstractmethod
    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Learn from a batch of evaluation results.

        Args:
            batch_results: List of dicts, each containing:
                - input: str
                - prediction: str
                - ground_truth: str
                - was_correct: bool
                - metadata: dict (optional)

        This is called AFTER all predictions in the batch are complete.
        The memory system can analyze patterns across the batch.
        """
        pass

    def get_context_length(self) -> int:
        """Return the character length of context actually injected per query.

        Override in subclasses where the injected context differs from stored state
        (e.g., fewshot memories that store all examples but only inject N).
        """
        return len(self.get_state())

    @abstractmethod
    def get_state(self) -> str:
        """Return serializable state for checkpointing."""
        pass

    @abstractmethod
    def set_state(self, state: str) -> None:
        """Restore state from serialized representation."""
        pass

"""Query-conditioned few-shot retrieval with a fixed context budget."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """Use the related examples as demonstrations. Their answers are labeled feedback.

{examples}

Problem:
{input}

Follow the problem's own instructions and return JSON with a concise final_answer.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]"}}"""


def _features(text: str) -> list[str]:
    features: list[str] = []
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            features.extend(run[i : i + 2] for i in range(len(run) - 1))
            features.extend(run[i : i + 3] for i in range(len(run) - 2))
        else:
            features.append(run)
    return features


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _clip(text: str, limit: int = 1500) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


class Candidate(MemorySystem):
    """Select demonstrations by query similarity rather than recency or order."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.context_budget = 14000
        self._last_context_len = 0

    def _retrieve(self, query: str, limit: int = 14) -> list[dict[str, str]]:
        if not self.examples:
            return []
        docs = [_features(ex["input"]) for ex in self.examples]
        doc_freq: Counter[str] = Counter()
        for doc in docs:
            doc_freq.update(set(doc))
        avg_len = sum(map(len, docs)) / max(1, len(docs))
        qtf = Counter(_features(query))
        n_docs = len(docs)
        ranked: list[tuple[float, int]] = []
        for index, doc in enumerate(docs):
            tf = Counter(doc)
            score = 0.0
            for term, q_count in qtf.items():
                term_count = tf.get(term, 0)
                if not term_count:
                    continue
                df = doc_freq[term]
                idf = math.log(1.0 + (n_docs - df + 0.5) / (df + 0.5))
                denom = term_count + 1.2 * (
                    0.25 + 0.75 * len(doc) / max(1.0, avg_len)
                )
                score += min(q_count, 2) * idf * term_count * 2.2 / denom
            ranked.append((score, index))
        ranked.sort(key=lambda item: (item[0], item[1]), reverse=True)
        return [self.examples[index] for _, index in ranked[:limit]]

    def _format_examples(self, query: str) -> str:
        selected = self._retrieve(query)
        parts: list[str] = []
        used = 0
        for example in selected:
            part = f"Q: {_clip(example['input'])}\nA: {example['target']}"
            remaining = self.context_budget - used
            if remaining <= 0:
                break
            if len(part) > remaining:
                if remaining < 80:
                    break
                part = part[: remaining - 3] + "..."
            parts.append(part)
            used += len(part) + 2
        self._last_context_len = used
        return "\n\n".join(parts) or "No learned examples yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples = self._format_examples(input)
        response = self.call_llm(_PROMPT.format(examples=examples, input=input))
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "retrieved_examples": 0 if examples == "No learned examples yet." else len(self._retrieve(input)),
            "memory_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for row in batch_results:
            self.examples.append(
                {"input": _source_text(row), "target": str(row["ground_truth"])}
            )

    def get_context_length(self) -> int:
        return self._last_context_len

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])

"""Similarity-gated replay of prior errors as corrected contrastive examples."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """Learn from the feedback examples below. In every correction, the model answer is known to be wrong and the corrected answer is authoritative. Use a similar correction to avoid repeating its mistake. The examples are guidance; follow the current problem's instructions.

{memory}

Current problem:
{input}

Return JSON with a concise final_answer.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]"}}"""


def _features(text: str) -> set[str]:
    result: set[str] = set()
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            result.update(run[i : i + 2] for i in range(len(run) - 1))
            result.update(run[i : i + 3] for i in range(len(run) - 2))
        else:
            result.add(run)
    return result


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _clip(text: str, limit: int = 1050) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


class Candidate(MemorySystem):
    """Store feedback outcomes and retrieve the most relevant corrections."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, Any]] = []
        self.context_budget = 9000
        self._last_context_len = 0

    def _rank(self, query: str, rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        if not rows:
            return []
        query_features = _features(query)
        if not query_features:
            return rows[-5:][::-1]
        row_features = [_features(row["input"]) for row in rows]
        df: Counter[str] = Counter()
        for features in row_features:
            df.update(features)
        n_rows = len(rows)
        weights = {
            token: math.log(1.0 + (n_rows - df[token] + 0.5) / (df[token] + 0.5))
            for token in query_features
        }
        denom = sum(weights.values()) or 1.0
        scores = [
            (sum(weights[token] for token in query_features & features) / denom, i)
            for i, features in enumerate(row_features)
        ]
        scores.sort(key=lambda item: (item[0], item[1]), reverse=True)
        return [rows[i] for score, i in scores[:6] if score > 0]

    def _format_memory(self, query: str) -> str:
        failures = [row for row in self.examples if not row["was_correct"]]
        successes = [row for row in self.examples if row["was_correct"]]
        corrections = self._rank(query, failures)
        anchors = self._rank(query, successes)[:2]
        parts: list[str] = []
        used = 0
        for row in corrections:
            bad = _clip(str(row.get("prediction", "")), 180)
            part = (
                f"Similar case: {_clip(row['input'])}\n"
                f"Known wrong model answer: {bad}\n"
                f"Corrected answer: {row['target']}"
            )
            if used + len(part) > self.context_budget:
                continue
            parts.append(part)
            used += len(part) + 2
        for row in anchors:
            part = f"Related labeled case: {_clip(row['input'], 700)}\nAnswer: {row['target']}"
            if used + len(part) > self.context_budget:
                continue
            parts.append(part)
            used += len(part) + 2
        self._last_context_len = used
        return "\n\n".join(parts) or "No feedback examples yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        memory = self._format_memory(input)
        response = self.call_llm(_PROMPT.format(memory=memory, input=input))
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "correction_examples": sum(not row["was_correct"] for row in self.examples),
            "memory_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for row in batch_results:
            self.examples.append(
                {
                    "input": _source_text(row),
                    "prediction": str(row.get("prediction", "")),
                    "target": str(row["ground_truth"]),
                    "was_correct": bool(row.get("was_correct", False)),
                }
            )

    def get_context_length(self) -> int:
        return self._last_context_len

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])

"""Few-Shot Memory - baseline using all training examples as demonstrations.

Accumulates (raw_question, ground_truth) pairs during training, uses them as
few-shot context at test time. Uses raw questions (not full preprocessed prompts)
to avoid repeating task context per example — matching MCE reproduce behavior.

Variant:
- FewShotAll: Up to 9999 examples
Uses a global max_chars=50000 cap (matching MCE reproduce).
"""

import hashlib
import json
import random
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem below based on the examples provided.

{examples_section}

**Problem:**
{input}

**Instructions:**
- Follow the patterns shown in the examples above
- Respond in JSON format

{{"reasoning": "[your reasoning]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000


def _seed_for_input(input: str) -> int:
    """Return a stable per-input seed across Python processes."""
    return int.from_bytes(hashlib.sha256(input.encode()).digest()[:8], "big")


class FewShotMemory(MemorySystem):
    """Few-shot baseline - accumulate all examples, use as demonstrations."""

    def __init__(
        self,
        llm: LLMCallable,
        max_examples: int = 50,
    ):
        super().__init__(llm)
        self.max_examples = max_examples
        self.examples: list[dict[str, str]] = []

    def _format_examples_section(self, seed: int | None = None) -> str:
        """Format examples as few-shot demonstrations, respecting global char limit.

        Uses raw_question (short Q/A) when available to avoid repeating task
        context per example. Falls back to full input for non-MCE datasets.

        Args:
            seed: If provided, randomly sample max_examples and shuffle order.
                  Each eval instance should pass a different seed for diversity.
        """
        if not self.examples:
            return ""

        if seed is not None and len(self.examples) > self.max_examples:
            rng = random.Random(seed)
            to_use = rng.sample(self.examples, self.max_examples)
        else:
            to_use = self.examples[-self.max_examples :]
            if seed is not None:
                rng = random.Random(seed)
                to_use = list(to_use)
                rng.shuffle(to_use)

        parts = []
        total_chars = 0
        for ex in to_use:
            # Use raw_question for demos (avoids repeating task context per example)
            question = ex.get("raw_question", ex["input"])
            part = f"Q: {question}\nA: {ex['target']}"
            if total_chars + len(part) > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2  # \n\n separator

        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction using accumulated few-shot examples."""
        seed = _seed_for_input(input)
        examples_section = self._format_examples_section(seed=seed)
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )

        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")

        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Accumulate all examples with ground truth labels."""
        for r in batch_results:
            ex = {"input": r["input"], "target": r["ground_truth"]}
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        """Return length of the examples section actually injected per query."""
        return len(self._format_examples_section())

    def get_state(self) -> str:
        """Serialize memory state."""
        return json.dumps({"examples": self.examples}, indent=2)

    def set_state(self, state: str) -> None:
        """Restore memory state from JSON."""
        data = json.loads(state)
        self.examples = data.get("examples", [])

"""Compact answer-pattern profiles learned from labeled examples."""

import json
import math
import re
from collections import Counter, defaultdict
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """The learned answer patterns below summarize feedback from prior examples. Use them as candidate guidance, then inspect the current problem and follow its instructions. An answer may contain one or several output labels; do not omit a supported part.

{profiles}

Current problem:
{input}

Return JSON with a concise final_answer.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]"}}"""


def _features(text: str) -> Counter[str]:
    result: Counter[str] = Counter()
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            result.update(run[i : i + 2] for i in range(len(run) - 1))
            result.update(run[i : i + 3] for i in range(len(run) - 2))
        else:
            result[run] += 1
    return result


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _clip(text: str, limit: int = 600) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


class Candidate(MemorySystem):
    """Represent training feedback as answer profiles with supporting cases."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self._last_context_len = 0
        self.profile_budget = 8500

    def _profiles(self, query: str) -> str:
        if not self.examples:
            self._last_context_len = 0
            return "No learned answer patterns yet."

        docs = [_features(row["input"]) for row in self.examples]
        document_frequency: Counter[str] = Counter()
        for doc in docs:
            document_frequency.update(doc.keys())
        count = len(docs)
        idf = {
            token: math.log(1.0 + (count + 1) / (frequency + 1))
            for token, frequency in document_frequency.items()
        }

        doc_vectors: list[dict[str, float]] = []
        query_counts = _features(query)
        query_vector = {
            token: value * idf.get(token, 0.0) for token, value in query_counts.items()
        }
        query_norm = math.sqrt(sum(value * value for value in query_vector.values())) or 1.0
        query_vector = {token: value / query_norm for token, value in query_vector.items()}

        class_vectors: dict[str, dict[str, float]] = defaultdict(lambda: defaultdict(float))
        class_counts: Counter[str] = Counter()
        for row, doc in zip(self.examples, docs):
            raw_total = sum(doc.values()) or 1
            vector = {
                token: value / raw_total * idf.get(token, 0.0)
                for token, value in doc.items()
            }
            norm = math.sqrt(sum(value * value for value in vector.values())) or 1.0
            vector = {token: value / norm for token, value in vector.items()}
            doc_vectors.append(vector)
            label = row["target"]
            class_counts[label] += 1
            for token, value in vector.items():
                class_vectors[label][token] += value

        prototypes: dict[str, dict[str, float]] = {}
        for label, vector in class_vectors.items():
            averaged = {token: value / class_counts[label] for token, value in vector.items()}
            norm = math.sqrt(sum(value * value for value in averaged.values())) or 1.0
            prototypes[label] = {token: value / norm for token, value in averaged.items()}

        class_scores = []
        for label, vector in prototypes.items():
            score = sum(query_vector.get(token, 0.0) * value for token, value in vector.items())
            class_scores.append((score, label))
        class_scores.sort(key=lambda item: (item[0], class_counts[item[1]], item[1]), reverse=True)

        cards: list[str] = []
        used = 0
        for score, label in class_scores[:8]:
            best_index = max(
                (index for index, row in enumerate(self.examples) if row["target"] == label),
                key=lambda index: sum(
                    query_vector.get(token, 0.0) * value
                    for token, value in doc_vectors[index].items()
                ),
            )
            support = _clip(self.examples[best_index]["input"])
            card = (
                f"Observed answer pattern: {label} "
                f"(support={class_counts[label]}, profile_match={score:.3f})\n"
                f"Closest supporting case: {support}"
            )
            if used + len(card) > self.profile_budget:
                continue
            cards.append(card)
            used += len(card) + 2
        self._last_context_len = used
        return "\n\n".join(cards) or "No matching answer profiles."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        profiles = self._profiles(input)
        response = self.call_llm(_PROMPT.format(profiles=profiles, input=input))
        answer = extract_json_field(response, "final_answer")
        return answer, {"full_response": response, "answer_patterns": len(self.examples)}

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for row in batch_results:
            self.examples.append(
                {"input": _source_text(row), "target": str(row["ground_truth"])}
            )

    def get_context_length(self) -> int:
        return self._last_context_len

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])

